 [CommandMethod("HLCADTABLEFORMATREADTESTV2",CommandFlags.Session)]public void Run(){var a=App.DocumentManager.MdiActiveDocument.Editor.GetString(new PromptStringOptions("\nFolder:"){AllowSpaces=true});string dir=a.StringResult.Trim('"'),receipt=Path.Combine(dir,"table_format_read.receipt.json"),path=Path.Combine(dir,"table_format_fixture.dwg");try{Need(!File.Exists(receipt)&&!File.Exists(path),"OUTPUT_EXISTS");string handle,styleHandle;using(var db=new Database(true,true)){using(var tr=db.TransactionManager.StartTransaction()){var st=(TextStyleTable)tr.GetObject(db.TextStyleTableId,OpenMode.ForWrite);var s=new TextStyleTableRecord{Name="TableFont",FileName="simplex.shx",BigFontFileName="gbcbig.shx"};st.Add(s);tr.AddNewlyCreatedDBObject(s,true);styleHandle=s.Handle.ToString();var b=(BlockTableRecord)tr.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForWrite);var ts=new TableStyle();ts.SetTextStyle(s.ObjectId,(int)(RowType.TitleRow|RowType.HeaderRow|RowType.DataRow));ts.SetTextHeight(7,(int)RowType.TitleRow);ts.SetTextHeight(3.5,(int)(RowType.HeaderRow|RowType.DataRow));ts.PostTableStyleToDatabase(db,"InheritedTableStyle");tr.AddNewlyCreatedDBObject(ts,true);var t=new Table();t.TableStyle=ts.ObjectId;t.SetSize(3,2);t.SetRowHeight(15);t.SetColumnWidth(40);b.AppendEntity(t);tr.AddNewlyCreatedDBObject(t,true);for(int r=0;r<3;r++)for(int c=0;c<2;c++){t.Cells[r,c].TextString="cell"+r+"_"+c;if(r==2&&c==1){t.Cells[r,c].TextStyleId=s.ObjectId;t.Cells[r,c].TextHeight=5;}}handle=t.Handle.ToString();tr.Commit();}db.SaveAs(path,DwgVersion.AC1032);}string sha=NativeGeometryReadV1.Hash(path);object rows;var touched=new List<string>();using(var db=new Database(false,true)){db.ReadDwgFile(path,FileOpenMode.OpenForReadAndAllShare,true,"");db.CloseInput(true);ObjectEventHandler change=(s,e)=>touched.Add(e.DBObject.Handle.ToString());ObjectErasedEventHandler erased=(s,e)=>touched.Add(e.DBObject.Handle.ToString());db.ObjectModified+=change;db.ObjectAppended+=change;db